package main

import (
    "errors"
    "fmt"
    "os"
)

// Config holds the settings read from the environment at startup.
type Config struct {
    Listen  string
    DataDir string
}

// LoadConfig reads the two environment variables the daemon needs and
// returns an error if either one is missing.
func LoadConfig() (Config, error) {
    listen := os.Getenv("LISTEN_ADDR")
    if listen == "" {
        return Config{}, errors.New("LISTEN_ADDR is not set")
    }
    dir := os.Getenv("DATA_DIR")
    if dir == "" {
        return Config{}, errors.New("DATA_DIR is not set")
    }
    return Config{Listen: listen, DataDir: dir}, nil
}

func main() {
    cfg, err := LoadConfig()
    if err != nil {
        fmt.Fprintln(os.Stderr, "startup failed:", err)
        os.Exit(1)
    }
    fmt.Println("listening on", cfg.Listen, "with data in", cfg.DataDir)
}

